$ErrorActionPreference='Stop'`n$ENGINE = $args[0]`n$NM = Join-Path $ENGINE 'dsh/node_modules'`nif (-not (Test-Path $NM)) { Write-Host 'engine layout wrong'; exit 1 }`n$PY = 'C:\Users\1\AppData\Local\Programs\Python\Python312\python.exe'`n`n$py1 = @'`nimport sys, pathlib, re`nroot = pathlib.Path(sys.argv[1])`nhelper = '''`n// dsh-ios-shim:platform - iOS \u7684 Node \u62a5 process.platform === 'ios'\uff0c`n// \u800c\u5f15\u64ce\u53ea\u8ba4 'darwin'\u3002Darwin \u5185\u6838\u63a5\u53e3\u5728 iOS \u4e0a\u4e00\u81f4\u3002`nfunction __dshNormalizePlatform(p) {`n\tif (p === "ios" || p === "iphoneos" || p === "iphonesimulator") return "darwin";`n\treturn p;`n}`nconst __dshPlatformDesc = Object.getOwnPropertyDescriptor(process, "platform");`nif (__dshPlatformDesc && __dshPlatformDesc.value !== "darwin") {`n\ttry { Object.defineProperty(process, "platform", { ...__dshPlatformDesc, value: "darwin" }); } catch (e) {}`n}`n'''`nn = 0`nfor f in root.rglob('*.js'):`n    s = f.read_text(encoding='utf-8', errors='surrogateescape')`n    if '__dshNormalizePlatform' in s:`n        continue`n    orig = s`n    s = re.sub(r'function createProcessInspector\(platform = process\.platform, arch = process\.arch, internals = DEFAULT_INTERNALS\) \{',`n               'function createProcessInspector(platform = process.platform, arch = process.arch, internals = DEFAULT_INTERNALS) {\n\tplatform = __dshNormalizePlatform(platform);',`n               s, count=1)`n    s = re.sub(r'throw new Error\(`subprocess-local: terminal inspection is unsupported on platform \$\{platform\}`\);',`n               'return new MacProcessInspector(internals); // dsh-ios-shim:platform', s, count=1)`n    if s != orig:`n        s = helper + '\n' + s`n        f.write_text(s, encoding='utf-8', errors='surrogateescape')`n        n += 1`n        print('  patched', f)`nprint('  files:', n)`n'@`n`n$s1 = Join-Path $NM '@deepseek-ai/dsh-subprocess-local/lib'`nif (Test-Path $s1) { $py1 | & $PY - $s1 } else { Write-Host 'S1 dir missing' }`n'---'`n$s1 -replace '\\','/'